export class ApiError extends Error {
  response: Response;
  constructor(
    response: Response,
    message?: string | undefined,
    options?: ErrorOptions | undefined,
    ...other: any[]
  ) {
    super(message, options, ...(other as []));
    this.response = response;
  }
}

export class Api {
  baseUrl: string;
  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }
  getFetchConfig = (config: RequestInit) => {
    const headers = {
      "Content-Type": "application/json",
      ...(config?.headers || {}),
    };
    const requestInit: RequestInit = {
      ...config,
      headers,
    };
    return requestInit;
  };
  async request(
    method: string = "GET",
    endpoint: string,
    data: any,
    config: RequestInit
  ) {
    const url = new URL(endpoint, this.baseUrl).toString();
    const response = await fetch(url, {
      body: data ? JSON.stringify(data) : undefined,
      method,
      headers: {
        ...config.headers,
      },
    });
    if (!response.ok) {
      throw new ApiError(response, "Failed Api Request for " + endpoint);
    }
    const text = await response.text();
    const jsonData = text.length ? JSON.parse(text) : {};
    return { data: jsonData };
  }

  async post(endpoint: string, data: any, config: RequestInit = {}) {
    return this.request("POST", endpoint, data, this.getFetchConfig(config));
  }
  async get(endpoint: string, config: RequestInit = {}) {
    return this.request("GET", endpoint, null, this.getFetchConfig(config));
  }
  async put(endpoint: string, data: any, config: RequestInit = {}) {
    return this.request("PUT", endpoint, data, this.getFetchConfig(config));
  }
  async delete(endpoint: string, config: RequestInit = {}) {
    return this.request("DELETE", endpoint, null, this.getFetchConfig(config));
  }
}

import React from 'react';
import PropTypes from 'prop-types';
import { isSameDay } from 'date-fns';
import { useMessageStore } from '../../store';
import MessageReportWindow from '../ReportMessage/MessageReportWindow';
import isMessageSequential from '../../lib/isMessageSequential';
import isMessageLastSequential from '../../lib/isMessageLastSequential';
import { Message } from '../Message';
import LocalAIMessage from '../LocalAIMessage';

const ThreadMessageList = ({
  threadMessages,
  threadMainMessage,
  catchUps = [],
  onDismissCatchUp,
}) => {
  const showReportMessage = useMessageStore((state) => state.showReportMessage);
  const messageToReport = useMessageStore((state) => state.messageToReport);

  const isMessageNewDay = (current, previous) =>
    !previous || !isSameDay(new Date(current.ts), new Date(previous.ts));

  const sortedMessages = [...(threadMessages || []), threadMainMessage]
    .filter(Boolean)
    .sort((a, b) => new Date(a.ts) - new Date(b.ts));

  return (
    <>
      {sortedMessages.map((msg, index, arr) => {
        const prev = arr[index - 1];
        const next = arr[index + 1];
        const newDay = isMessageNewDay(msg, prev);
        const sequential = isMessageSequential(msg, prev, 300);
        const lastSequential = sequential && isMessageLastSequential(msg, next);

        return (
          <Message
            key={msg._id}
            message={msg}
            newDay={newDay}
            sequential={sequential}
            lastSequential={lastSequential}
            type="thread"
            showAvatar
          />
        );
      })}
      {catchUps.map((catchUp) => (
        <LocalAIMessage
          key={catchUp.id}
          catchUp={catchUp}
          onDismiss={onDismissCatchUp}
        />
      ))}
      {showReportMessage && <MessageReportWindow messageId={messageToReport} />}
    </>
  );
};

export default ThreadMessageList;

ThreadMessageList.propTypes = {
  threadMessages: PropTypes.arrayOf(PropTypes.object),
  threadMainMessage: PropTypes.object,
  catchUps: PropTypes.arrayOf(PropTypes.object),
  onDismissCatchUp: PropTypes.func,
};

